-- PT124-S2-Q25. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT124-S2-Q25$batch11$ AND q.stimulus=$batch11$Most serious students are happy students, and most serious students go to graduate school. Furthermore, all students who go to graduate school are overworked.$batch11$ AND q.prompt=$batch11$Which one of the following can be properly inferred from the statements above?$batch11$ AND q.correct_choice=$batch11$B$batch11$) THEN RAISE EXCEPTION 'Question changed: PT124-S2-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT124-S2-Q25$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT124-S2-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT124-S2-Q25$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Most serious students are happy. Most serious students go to graduate school. All students who go to graduate school are overworked.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Two "most" statements about the same group must overlap. More than half of serious students are happy and more than half go to graduate school, so some serious students are both. Those graduate students are overworked. So some happy students are overworked.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Some happy students are overworked.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT124-S2-Q25$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$We know some overworked students are happy, not most. Plenty of overworked students may not be serious or happy.$batch11$), ($batch11$B$batch11$, $batch11$Two "mosts" overlap, so some serious students are happy and in graduate school. Graduate students are overworked.$batch11$), ($batch11$C$batch11$, $batch11$Some serious students are overworked. This says every overworked student is serious.$batch11$), ($batch11$D$batch11$, $batch11$The overlap could be complete: every serious graduate student could be happy.$batch11$), ($batch11$E$batch11$, $batch11$Only most serious students go to graduate school. The rest might not be overworked.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT124-S2-Q25$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
